mapper.select:
select * from club_edition_hours
where topic_id = #{topicId} and club_id = #{clubId} and hour_kind = #{hourKind}
for update

mapper.update:
update club_edition_hours
set confirmed_actual_hours = null, confirmed_by = null, confirmed_at = null,
    confirm_status = 'REPORTED', update_time = CURRENT_TIMESTAMP(3)
where topic_id = #{topicId} and club_id = #{clubId} and hour_kind = #{hourKind}
  and confirm_status = 'CONFIRMED' and confirmed_at = #{previousConfirmedAt}

update club_quality_decision
set decision_status = 'CONFIRMED', amount = #{amount}, reason = #{reason},
    confirmed_by = #{confirmedBy}, confirmed_at = #{confirmedAt}
where topic_id = #{topicId} and club_id = #{clubId} and dimension = #{dimension}
  and is_current = 1 and decision_status = 'PENDING'
